import { readdir, readFile, writeFile } from "node:fs/promises";
import { extname, join, sep } from "node:path";
import { fileURLToPath } from "node:url";

const GENERATED_ROOT = fileURLToPath(new URL("../src/gen/", import.meta.url));
const SPDX_MARKER = "SPDX-FileCopyrightText";
const GENERATED_HEADER = `// SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
// SPDX-License-Identifier: Apache-2.0
// @generated by Kubb. DO NOT EDIT.

`;

// @kubb/plugin-ts and @kubb/plugin-zod emit this banner by default (no
// `output.banner` configured for either plugin); @kubb/plugin-axios emits
// the shorter custom banner set via `output.banner` in kubb.config.ts. Both
// already assert "generated"/"do not edit", so leaving them in place would
// duplicate that assertion underneath GENERATED_HEADER above.
const KUBB_DEFAULT_BANNER =
  /^\/\*\*\n\* Generated by Kubb \(https:\/\/kubb\.dev\/\)\.\n\* Do not edit manually\.\n\*\/\n+/;
const KUBB_CUSTOM_BANNER = /^\/\/ @generated by Kubb\. DO NOT EDIT\.\n+/;

function stripKubbBanner(source) {
  return source
    .replace(KUBB_DEFAULT_BANNER, "")
    .replace(KUBB_CUSTOM_BANNER, "");
}

// @kubb/plugin-axios's readBytes() template delegates `yield*` to a bare
// AsyncIterable, whose iterator defaults `next()` to accept `undefined`,
// while the containing AsyncGenerator defaults to sending `unknown` -
// TypeScript rejects the delegation (TS2766) even though the two are
// runtime-equivalent. Rewriting the delegation as an explicit `for await`
// loop iterates via the same Symbol.asyncIterator protocol without
// generator-to-generator delegation, sidestepping the mismatch.
const YIELD_STAR_STREAM = "    yield* stream\n    return\n  }";
const YIELD_STAR_STREAM_FIX =
  "    for await (const chunk of stream) {\n      yield chunk\n    }\n    return\n  }";

function fixYieldStarDelegation(file, source) {
  if (!file.endsWith(`${join(".kubb", "client.ts")}`)) {
    return source;
  }
  if (source.includes(YIELD_STAR_STREAM_FIX)) {
    return source;
  }
  if (!source.includes(YIELD_STAR_STREAM)) {
    throw new Error(
      `${file}: expected @kubb/plugin-axios's readBytes() "yield* stream" pattern was not found. ` +
        "Kubb may have changed its generated template - re-check whether the TS2766 workaround in this script is still needed.",
    );
  }
  return source.replace(YIELD_STAR_STREAM, YIELD_STAR_STREAM_FIX);
}

// @kubb/plugin-zod emits `<schema>.optional().default({})` for an
// object-typed field whose nested schema is itself omittable. When that
// nested schema gives every one of its own fields a `.default(...)`, its
// *output* type has no optional properties, so zod v4 rejects the bare `{}`
// literal (it only accepts the input shape, not the output shape, for
// `.default()`). Re-parsing `{}` through the nested schema at the call site
// produces the correctly-shaped default without duplicating its field
// defaults as a second literal that could drift out of sync.
const NAMED_SCHEMA_OPTIONAL_DEFAULT_EMPTY_OBJECT =
  /\b([A-Za-z_$][\w$]*)\.optional\(\)\.default\(\{\}\)/g;

function fixOptionalDefaultEmptyObjectMismatch(file, source) {
  if (!file.includes(`${sep}zod${sep}`)) {
    return source;
  }
  return source.replace(
    NAMED_SCHEMA_OPTIONAL_DEFAULT_EMPTY_OBJECT,
    (_match, schemaName) =>
      `${schemaName}.optional().default(() => ${schemaName}.parse({}))`,
  );
}

async function generatedTypeScriptFiles(directory) {
  const entries = await readdir(directory, { withFileTypes: true });
  const files = [];

  for (const entry of entries) {
    const path = join(directory, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await generatedTypeScriptFiles(path)));
    } else if (entry.isFile() && extname(entry.name) === ".ts") {
      files.push(path);
    }
  }

  return files;
}

for (const file of await generatedTypeScriptFiles(GENERATED_ROOT)) {
  const original = await readFile(file, "utf8");
  const preamble = original.slice(0, 512);
  const withHeader = preamble.includes(SPDX_MARKER)
    ? original
    : GENERATED_HEADER + stripKubbBanner(original);
  const withYieldStarFix = fixYieldStarDelegation(file, withHeader);
  const patched = fixOptionalDefaultEmptyObjectMismatch(file, withYieldStarFix);
  if (patched !== original) {
    await writeFile(file, patched);
  }
}
